import numpy as np, torch, model
torch.manual_seed(0); np.random.seed(0)
net=model.load(); neg=model.negatives()
w=torch.tensor(np.load('contrast_c1_blocks.2_k14.npy')); b=0.2683
def dec(xi,c):
    x=torch.as_tensor(xi,dtype=torch.float32).clone(); c=torch.as_tensor(c,dtype=torch.float32)
    fired=torch.zeros(x.shape[0])
    for k in range(20):
        t=torch.full((x.shape[0],),1-k/20)
        v,a=net.velocity(x,t,c,("blocks.2",))
        if k<15: fired+=(a["blocks.2"]@w+b>0).float()
        x=x-v/20
    return x.numpy(),fired.numpy()
