o=np.argsort(Cr[idx])
for j in idx[o][::4]: print('F c=%.2f a=(%.2f,%.2f) n=%d'%(Cr[j],ar[j,0],ar[j,1],fr[j]))
a64=np.asarray(neg['a']); c64=np.asarray(neg['c']); u=np.asarray(neg['uid'])
