import numpy as np, torch, model
net=model.load()
w=torch.tensor(np.load('contrast_c0_blocks.2_k12.npy')); b0=0.7369
xi=torch.tensor(np.load('s16_xi.npy')); c=np.load('s16_c.npy')
class G:
    def __init__(s,dv,lo,hi):
        s.layer='out'; s.dv=torch.tensor(dv,dtype=torch.float32); s.lo=lo; s.hi=hi
    def fires(s,feats,t):
        k=torch.round((1-t)*20)
        return ((feats['blocks.2']@w+b0)>0)&(k>=s.lo)&(k<s.hi)
    def contribution(s,feats): return s.dv.expand(feats['out_act'].shape[0],2)
a0,S,A=model.decode(net,xi,c,save_states=True,capture=('blocks.2',))
sc=(A['blocks.2']@w+b0).numpy()
idx=np.where((sc[:16]>-0.5).any(0))[0]
def track(a,cc):
    _,Af=net.velocity(torch.as_tensor(a),torch.full((len(a),),0.05),torch.as_tensor(cc),('blocks.2',),count=False)
    return ((Af['blocks.2']@w+b0)>0).numpy()
ref_mask=~(sc[:13]>0).any(0)  # kept samples
ra=a0.numpy()[ref_mask]; rc=c[ref_mask]
def offd(a,cc):
    a=np.asarray(a); out=[]
    for j in range(len(a)):
        m=np.abs(rc-cc[j])<0.05
        out.append(np.sqrt(((ra[m]-a[j])**2).sum(1)).min())
    return np.array(out)
tr0=track(a0[idx].numpy(),c[idx]); print('subset',len(idx),'track0',tr0.sum())
