def ed(X,Xc,Y,Yc,n=3000):
    rng=np.random.default_rng(0)
    X=np.c_[X,3*Xc]; Y=np.c_[Y,3*Yc]
    X=X[rng.choice(len(X),n)]; Y=Y[rng.choice(len(Y),n)]
    d=lambda P,Q: np.sqrt(((P[:,None]-Q[None])**2).sum(-1)).mean()
    return 2*d(X,Y)-d(X,X)-d(Y,Y)
